function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 2000) return 's needs 1 to 2000 characters.';
  if (!/^[a-z()]*$/.test(s)) return 's may only contain lowercase letters and parentheses.';
  let depth = 0;
  for (const ch of s) {
    if (ch === '(') depth++;
    else if (ch === ')' && --depth < 0) return 'Every ")" needs an earlier matching "(".';
  }
  if (depth !== 0) return 'Every "(" needs a matching ")".';
  return null;
}

