function reverseParentheses(s) {
  const pair = new Array(s.length);
  const stack = [];
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') {
      stack.push(i);
    } else if (s[i] === ')') {
      const open = stack.pop();
      pair[i] = open;
      pair[open] = i;
    }
  }

  const result = [];
  let direction = 1;
  for (let i = 0; i < s.length; i += direction) {
    if (s[i] === '(' || s[i] === ')') {
      i = pair[i];
      direction = -direction;
    } else {
      result.push(s[i]);
    }
  }
  return result.join('');
}

