function reverseParentheses(s) {
  let text = s;
  for (;;) {
    const close = text.indexOf(')');
    if (close === -1) return text;
    const open = text.lastIndexOf('(', close);
    const inside = text.slice(open + 1, close).split('').reverse().join('');
    text = text.slice(0, open) + inside + text.slice(close + 1);
  }
}

