function generate(rand, size) {
  const target = size === 'large' ? 1990 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 12);
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  let s = '';
  let depth = 0;
  // Grow the string while leaving room to close every open pair at the end.
  while (s.length + depth < target) {
    const r = rand();
    if (r < 0.2 && s.length + depth + 2 <= target) {
      s += '(';
      depth++;
    } else if (r < 0.4 && depth > 0) {
      s += ')';
      depth--;
    } else {
      s += letters[Math.floor(rand() * letters.length)];
    }
  }
  return [s + ')'.repeat(depth)];
}
